  values ((select id from programas_base where clinica_id is null and nombre = 'Comprender el Engaño'), 'Clase 12', 'Grupo 3', 12, $j${"entrenamiento:A→B": "Tú tienes los lápices y sabes que yo no sé que intentas esconderlos. ¿Dónde los escondes?"}$j$::jsonb, $j${"A→B": "La maceta"}$j$::jsonb, $j${"entrenamiento:A→B": ["El estuche", "La maceta"]}$j$::jsonb) returning id)
insert into estimulos_rft_base (clase_base_id, etiqueta, posicion, nombre, concepto_imagen)
select id, 'A12', 'A', $j$Tú tienes los lápices y sabes que yo no sé que intentas esconderlos.$j$, null from nueva union all select id, 'B12', 'B', $j$La maceta$j$, null from nueva;
